using System.Collections.Generic;

namespace EmergencyPriority
{
    // Machine-translated UI strings (Options + panels). English is the source of truth; Get() returns the
    // locale string when present, else English. Community corrections welcome.
    public static class Translations
    {
        public static string Get(string key, string locale) =>
            (Loc.TryGetValue(locale, out var lm) && lm.TryGetValue(key, out var lv)) ? lv
            : (En.TryGetValue(key, out var v) ? v : key);

        public static readonly Dictionary<string, string> En = new Dictionary<string, string>
        {
            { "opt.Enabled.L", "Enable Emergency Priority" },
            { "opt.Enabled.D", "Keeps responding fire engines, ambulances and police cars alive and moving through traffic jams. Off = vanilla behaviour." },
            { "opt.DespawnGuard.L", "Prevent stuck responders from despawning" },
            { "opt.DespawnGuard.D", "Vanilla deletes a responding vehicle once it is flagged as stuck in traffic, and the emergency waits for a re-dispatch. With the guard, the vehicle looks for a new route instead." },
            { "opt.AutoReroute.L", "Re-route around congestion" },
            { "opt.AutoReroute.D", "Vanilla plans the route once, at dispatch. With this on, a responder that sits blocked in a jam requests a fresh route that accounts for current traffic." },
            { "opt.RerouteAfterSeconds.L", "Re-route after (seconds blocked)" },
            { "opt.RerouteAfterSeconds.D", "How long a responder must be continuously stuck behind traffic before it looks for a detour." },
            { "grp.Group", "Responding vehicles" },
            { "grp.GroupGeneral", "General" },
        };

        public static readonly Dictionary<string, Dictionary<string, string>> Loc = new Dictionary<string, Dictionary<string, string>>
        {
                ["de-DE"] = new Dictionary<string, string> { ["opt.Enabled.L"]="Emergency Priority aktivieren", ["opt.Enabled.D"]="Hält ausrückende Feuerwehr-, Rettungs- und Polizeifahrzeuge am Leben und in Bewegung durch Staus. Aus = Vanilla-Verhalten.", ["opt.DespawnGuard.L"]="Verhindert das Verschwinden festsitzender Einsatzfahrzeuge", ["opt.DespawnGuard.D"]="Vanilla löscht ein ausrückendes Fahrzeug, sobald es als im Stau festsitzend markiert wird, und der Einsatz wartet auf eine erneute Entsendung. Mit dem Schutz sucht das Fahrzeug stattdessen eine neue Route.", ["opt.AutoReroute.L"]="Um Staus herum umleiten", ["opt.AutoReroute.D"]="Vanilla plant die Route nur einmal, bei der Entsendung. Ist dies an, fordert ein Einsatzfahrzeug, das blockiert im Stau steht, eine neue Route an, die den aktuellen Verkehr berücksichtigt.", ["opt.RerouteAfterSeconds.L"]="Umleiten nach (Sekunden blockiert)", ["opt.RerouteAfterSeconds.D"]="Wie lange ein Einsatzfahrzeug ununterbrochen hinter dem Verkehr festsitzen muss, bevor es einen Umweg sucht.", ["grp.Group"]="Einsatzfahrzeuge", ["grp.GroupGeneral"]="Allgemein", },
